def cycleLengthQueries(n, queries):
    res = []
    for a, b in queries:
        cnt = 1   # Start with 1 for the new edge
        x, y = a, b
        # Move up until both meet at LCA
        while x != y:
            if x > y:
                x //= 2
            else:
                y //= 2
            cnt += 1
        res.append(cnt)
    return res
